/* BrightAI Pricing Recommender — Gemini 2.5 Flash | brightai.site */
(function () {
  'use strict';

  const GEMINI_API_KEY = 'AIzaSyBFMmyO7sgXaSbF47zd3rbO6I9MfhbYLK8';
  const GEMINI_MODEL   = 'gemini-2.5-flash';
  const GEMINI_URL     = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent`;

  /* ─── نموذج التوصية ─── */
  const form         = document.getElementById('recommender-form');
  const teamInput    = document.getElementById('team-size');
  const sectorSelect = document.getElementById('sector-type');
  const resultEl     = document.getElementById('recommender-result');
  const submitBtn    = document.getElementById('recommender-submit');

  if (form && teamInput && sectorSelect && resultEl && submitBtn) {
    const origLabel = submitBtn.innerHTML;

    function setLoading(on) {
      submitBtn.disabled = on;
      submitBtn.innerHTML = on
        ? '<i class="fa-solid fa-circle-notch fa-spin"></i> جارٍ التحليل...'
        : origLabel;
    }

    async function getRecommendation(teamSize, sector) {
      const prompt = `أنت مستشار مبيعات لمنصة BrightAI السعودية للذكاء الاصطناعي.
بناءً على المعطيات التالية:
- حجم الفريق: ${teamSize} شخص
- القطاع: ${sector}

قدّم توصية موجزة وواضحة (3-4 جمل) بالباقة الأنسب من ثلاث باقات:
1. أساسي (مجاني) — للتجربة والشركات الصغيرة جداً
2. احترافي (2,900 ر.س/شهر) — للشركات الناشئة والفرق الصغيرة حتى 50 شخص
3. مؤسسي (حسب الاحتياج) — للمؤسسات الكبيرة والجهات الحكومية

اذكر اسم الباقة بوضوح أولاً، ثم سبب التوصية، ثم خطوة تالية محددة. الأسلوب: مهني وموجز.`;

      const body = {
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.5, maxOutputTokens: 300 }
      };

      const res  = await fetch(GEMINI_URL, {
        method  : 'POST',
        headers : { 'Content-Type': 'application/json', 'x-goog-api-key': GEMINI_API_KEY },
        body    : JSON.stringify(body)
      });

      if (!res.ok) throw new Error(`HTTP ${res.status}`);

      const data = await res.json();
      return data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();

      const teamSize = parseInt(teamInput.value, 10);
      const sector   = sectorSelect.value;

      if (!teamSize || teamSize < 1) {
        resultEl.innerHTML = '<span style="color:#f87171">يرجى إدخال عدد أفراد الفريق.</span>';
        return;
      }
      if (!sector) {
        resultEl.innerHTML = '<span style="color:#f87171">يرجى اختيار القطاع.</span>';
        return;
      }

      setLoading(true);
      resultEl.innerHTML = '<span style="color:#94a3b8"><i class="fa-solid fa-circle-notch fa-spin"></i> جارٍ تحليل احتياجك...</span>';

      try {
        const rec = await getRecommendation(teamSize, sector);
        resultEl.innerHTML = `<div class="rec-result">
          <div class="rec-icon"><i class="fa-solid fa-robot"></i></div>
          <div class="rec-text">${rec.replace(/\n/g, '<br>')}</div>
          <div class="rec-actions">
            <a href="/consultation/" class="btn-primary" style="font-size:0.9rem;padding:10px 20px">
              <i class="fa-solid fa-calendar-check"></i> احجز استشارة
            </a>
            <a href="/contact/" class="btn-secondary" style="font-size:0.9rem;padding:10px 18px">
              تواصل معنا
            </a>
          </div>
        </div>`;
      } catch (err) {
        console.error('[BrightAI Pricing]', err);
        resultEl.innerHTML = '<span style="color:#f87171"><i class="fa-solid fa-triangle-exclamation"></i> تعذّر تحليل الاحتياج. حاول مرة أخرى.</span>';
      } finally {
        setLoading(false);
      }
    });
  }

  /* ─── أزرار الباقات (highlight تفاعلي) ─── */
  document.querySelectorAll('.plan-card').forEach(card => {
    card.addEventListener('mouseenter', () => {
      card.style.transform = 'translateY(-4px)';
      card.style.transition = 'transform 0.25s ease, box-shadow 0.25s ease';
      card.style.boxShadow = '0 24px 60px -20px rgba(0,0,0,0.5)';
    });
    card.addEventListener('mouseleave', () => {
      card.style.transform = '';
      card.style.boxShadow = '';
    });
  });

  /* ─── FAQ accordion (إن وجد) ─── */
  document.querySelectorAll('.faq-item').forEach(item => {
    const btn = item.querySelector('.faq-q');
    const ans = item.querySelector('.faq-a');
    if (!btn || !ans) return;

    btn.addEventListener('click', () => {
      const isOpen = ans.style.maxHeight && ans.style.maxHeight !== '0px';
      // أغلق الجميع
      document.querySelectorAll('.faq-a').forEach(a => { a.style.maxHeight = '0px'; });
      document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
      // افتح الحالي إذا كان مغلقاً
      if (!isOpen) {
        ans.style.maxHeight = ans.scrollHeight + 'px';
        item.classList.add('open');
      }
    });
  });

})();
